import * as React from "react"
import { cn } from "@/lib/utils"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { ArchiveStat } from "./archive-shared"
import type { ArchiveKpi } from "./archive-report"

export interface ArchiveAdminNavItem { id: string; label: string; icon?: React.ReactNode }
export interface ArchiveAdminNavGroup { heading: string; items: ArchiveAdminNavItem[] }

export interface ArchiveAdminPageProps {
  nav: ArchiveAdminNavGroup[]
  active: string
  onActiveChange?: (id: string) => void
  title: string
  kpis?: ArchiveKpi[]
  /** Section content, usually an `ArchiveAuditPage`/`ArchiveAdminListPage` with `bare`. */
  children: React.ReactNode
}

/** Administration (quản trị): grouped side navigation, section title, KPI tiles and the section content. */
export function ArchiveAdminPage({ nav, active, onActiveChange, title, kpis, children }: ArchiveAdminPageProps) {
  return (
    <div className="flex h-full min-h-0 flex-col gap-3 max-md:overflow-y-auto md:grid md:grid-cols-[220px_minmax(0,1fr)] md:items-start md:gap-4">
      <Select value={active} onValueChange={(v) => onActiveChange?.(v)}>
        <SelectTrigger aria-label="Quản trị lưu trữ" className="w-full shrink-0 bg-card md:hidden"><SelectValue /></SelectTrigger>
        <SelectContent>
          {nav.flatMap((g) => g.items.map((it) => <SelectItem key={it.id} value={it.id}>{it.label}</SelectItem>))}
        </SelectContent>
      </Select>
      <nav aria-label="Quản trị lưu trữ" className="sticky top-0 hidden flex-col gap-2.5 rounded-[9px] border bg-card p-2 shadow-sm md:flex">
        {nav.map((g) => (
          <div key={g.heading} className="flex flex-col gap-0.5">
            <div className="px-2.5 pt-1 pb-1.5 text-caption font-bold tracking-[0.05em] text-subtle-foreground uppercase">{g.heading}</div>
            {g.items.map((it) => (
              <button key={it.id} type="button" aria-current={it.id === active ? "page" : undefined} onClick={() => onActiveChange?.(it.id)}
                className={cn("flex w-full cursor-pointer items-center gap-2 rounded-md border px-2.5 py-[7px] text-left text-control outline-none hover:bg-secondary focus-visible:ring-2 focus-visible:ring-ring [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground", it.id === active ? "border-[color-mix(in_srgb,var(--primary)_22%,var(--card))] bg-accent font-bold text-primary [&_svg]:text-primary" : "border-transparent text-foreground")}>
                {it.icon}<span className="min-w-0 flex-1 truncate">{it.label}</span>
              </button>
            ))}
          </div>
        ))}
      </nav>
      <section className="flex h-full min-h-0 min-w-0 flex-col" aria-label={title}>
        <h2 className="mx-0 mt-0.5 mb-3 text-title font-bold text-foreground">{title}</h2>
        <div className="flex min-h-0 flex-1 flex-col gap-3">
          {kpis && <div className="grid shrink-0 grid-cols-2 gap-2.5 lg:grid-cols-5">{kpis.map((k) => <ArchiveStat key={k.label} {...k} />)}</div>}
          <div className="min-h-0 flex-1 max-md:min-h-[28rem]">{children}</div>
        </div>
      </section>
    </div>
  )
}

"use client"

// @dthu/ui 0.2.0 · block-archive
import * as React from "react"
import { AlertTriangle } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { DataTable, type Column } from "@/components/blocks/shell/data-table"
import {
  ArchiveChip, ArchiveRowMenu, ArchiveSelect, ArchiveTabs, ArchiveToolbar, withSortHeaders,
  type ArchiveColumn, type ArchiveRowAction, type ArchiveSelectProps, type ArchiveSort, type ArchiveTabItem,
} from "./archive-shared"

export interface ArchiveListChip { id: string; label: string }
export interface ArchiveBulkAction { id: string; label: string; onSelect: (ids: string[]) => void; destructive?: boolean }

export interface ArchiveListPageProps<T> {
  tabs?: ArchiveTabItem[]
  tab?: string
  onTabChange?: (v: string) => void
  search?: string
  onSearchChange?: (v: string) => void
  searchPlaceholder?: string
  chips?: ArchiveListChip[]
  activeChips?: string[]
  onChipToggle?: (id: string) => void
  selects?: (ArchiveSelectProps & { id: string })[]
  /** Content of the collapsible advanced-filter panel; enables the toggle button. */
  advanced?: React.ReactNode
  advancedOpen?: boolean
  onAdvancedOpenChange?: (open: boolean) => void
  actionLabel?: string
  onAction?: () => void
  onRefresh?: () => void
  /** Extra toolbar buttons placed before the primary action. */
  extraActions?: React.ReactNode
  columns: ArchiveColumn<T>[]
  rows: T[]
  getRowId: (row: T) => string
  sort?: ArchiveSort
  onSortChange?: (s: ArchiveSort) => void
  selectable?: boolean
  selectedIds?: string[]
  onSelectedChange?: (ids: string[]) => void
  bulkActions?: ArchiveBulkAction[]
  rowActions?: (row: T) => ArchiveRowAction[]
  /** Accessible name of a row for its action menu. */
  rowLabel?: (row: T) => string
  loading?: boolean
  error?: { title: string; description?: string; onRetry?: () => void }
  emptyTitle?: React.ReactNode
  emptyDescription?: React.ReactNode
  page?: number
  pageSize?: number
  total?: number
  onPageChange?: (p: number) => void
  onPageSizeChange?: (n: number) => void
  onRowClick?: (row: T) => void
  /** Panel shown left of the table (below the toolbar). */
  sidebar?: React.ReactNode
  /** Replaces the table (e.g. map view). */
  body?: React.ReactNode
  /** Tailwind min-width class of the table (it scrolls horizontally below it). */
  tableMinWidthClass?: string
  /** Kept for backward compatibility (the page never adds its own padding any more). */
  bare?: boolean
  className?: string
  /** Reserve the blank 51px trailing column the reference keeps even without row actions. */
  actionsColumn?: boolean
}

/** Toolbar (tabs, search, chips, filters, primary action) + DataTable with sort, selection, row menu, error/loading states. */
export function ArchiveListPage<T>(p: ArchiveListPageProps<T>) {
  const { tabs, tab, chips, activeChips = [], selects, selectedIds = [], rowActions, rowLabel, selectable, bulkActions, columns, rows, getRowId } = p
  const allSelected = rows.length > 0 && rows.every((r) => selectedIds.includes(getRowId(r)))
  const someSelected = rows.some((r) => selectedIds.includes(getRowId(r)))

  const cols: Column<T>[] = []
  if (selectable) {
    cols.push({
      key: "__select", className: "w-10",
      header: <Checkbox aria-label="Chọn tất cả" checked={allSelected ? true : someSelected ? "indeterminate" : false}
        onCheckedChange={(v) => p.onSelectedChange?.(v === true ? Array.from(new Set([...selectedIds, ...rows.map(getRowId)])) : selectedIds.filter((id) => !rows.some((r) => getRowId(r) === id)))} />,
      cell: (r) => {
        const id = getRowId(r)
        return <span onClick={(e) => e.stopPropagation()}><Checkbox aria-label={`Chọn ${rowLabel?.(r) ?? id}`} checked={selectedIds.includes(id)} onCheckedChange={(v) => p.onSelectedChange?.(v === true ? [...selectedIds, id] : selectedIds.filter((x) => x !== id))} /></span>
      },
    })
  }
  cols.push(...withSortHeaders(columns, p.sort, p.onSortChange))
  if (rowActions) cols.push({ key: "__actions", header: <span className="sr-only">Thao tác</span>, width: 120, align: "right", cell: (r) => <div className="flex justify-end"><ArchiveRowMenu label={rowLabel?.(r) ?? getRowId(r)} actions={rowActions(r)} /></div> })

  else if (p.actionsColumn) cols.push({ key: "__actions", header: <span className="sr-only">Thao tác</span>, width: 51, cell: () => null })

  const table = p.error ? (
    <div className="flex min-h-0 flex-1 items-start justify-center rounded-lg border bg-card p-8">
      <Alert variant="destructive" className="max-w-lg">
        <AlertTriangle />
        <AlertTitle>{p.error.title}</AlertTitle>
        <AlertDescription>{p.error.description}{p.error.onRetry && <div className="mt-3"><Button size="sm" variant="outline" className="bg-background text-foreground" onClick={p.error.onRetry}>Thử lại</Button></div>}</AlertDescription>
      </Alert>
    </div>
  ) : (
    <DataTable columns={cols} rows={rows} getRowId={getRowId} loading={p.loading} emptyTitle={p.emptyTitle} emptyDescription={p.emptyDescription}
      page={p.page} pageSize={p.pageSize} total={p.total} onPageChange={p.onPageChange} onPageSizeChange={p.onPageSizeChange} onRowClick={p.onRowClick} minWidthClass={p.tableMinWidthClass ?? (cols.length >= 8 ? "min-w-[64rem]" : cols.length >= 5 ? "min-w-[54rem]" : undefined)} />
  )

  return (
    <div className={cn("flex h-full min-h-0 flex-col gap-1.5 max-md:overflow-y-auto", p.className)}>
      <ArchiveToolbar
        leading={tabs && tab !== undefined ? <ArchiveTabs items={tabs} value={tab} onValueChange={p.onTabChange} /> : undefined}
        search={p.search} onSearchChange={p.onSearchChange} searchPlaceholder={p.searchPlaceholder}
        hasAdvanced={p.advanced !== undefined} advancedOpen={p.advancedOpen} onAdvancedOpenChange={p.onAdvancedOpenChange} onRefresh={p.onRefresh}
        actions={<>{p.extraActions}{p.actionLabel && <Button size="toolbar" onClick={p.onAction}>+ {p.actionLabel}</Button>}</>}>
        {chips?.map((c) => <ArchiveChip key={c.id} active={activeChips.includes(c.id)} onClick={() => p.onChipToggle?.(c.id)}>{c.label}</ArchiveChip>)}
        {selects?.map(({ id, ...s }) => <ArchiveSelect key={id} {...s} />)}
      </ArchiveToolbar>
      {p.advanced !== undefined && p.advancedOpen && <div className="shrink-0 rounded-lg border bg-card p-3">{p.advanced}</div>}
      {selectable && selectedIds.length > 0 && (
        <div role="region" aria-label="Thao tác hàng loạt" className="flex shrink-0 items-center gap-2 rounded-lg border border-primary/40 bg-accent px-3 py-2 text-sm">
          <span className="font-semibold text-accent-foreground" aria-live="polite">Đã chọn {selectedIds.length}</span>
          {bulkActions?.map((a) => <Button key={a.id} size="sm" variant={a.destructive ? "destructive" : "outline"} onClick={() => a.onSelect(selectedIds)}>{a.label}</Button>)}
          <Button size="sm" variant="ghost" className="ml-auto" onClick={() => p.onSelectedChange?.([])}>Bỏ chọn</Button>
        </div>
      )}
      <div className={cn("flex min-h-0 flex-1 flex-col gap-3.5 max-md:min-h-[26rem] md:flex-row", p.sidebar && "md:items-start")}>
        {p.sidebar}
        <div className={cn("flex min-h-0 min-w-0 flex-1 flex-col max-md:min-h-[24rem]", p.sidebar && "md:self-stretch")}>{p.body ?? table}</div>
      </div>
    </div>
  )
}

import * as React from "react"
import { Badge } from "@/components/ui/badge"
import { ArchiveListPage, type ArchiveListPageProps } from "./archive-list-page"
import { archiveMono, type ArchiveColumn } from "./archive-shared"

type StatusTone = "success" | "warning" | "destructive" | "info" | "secondary"
export interface ArchiveStatus { label: string; tone: StatusTone }
export const archiveStatus = (s: ArchiveStatus) => <Badge variant={s.tone}>{s.label}</Badge>
const bold = (v: React.ReactNode) => <span className="font-medium">{v}</span>

type ListProps<T> = Omit<ArchiveListPageProps<T>, "columns" | "getRowId">

// ---- Borrow / return
export interface ArchiveLoan { id: string; no: string; record: string; borrower: string; form: string; due: string; unit?: string; status: ArchiveStatus }
const loanColumns: ArchiveColumn<ArchiveLoan>[] = [
  { key: "no", header: "Số phiếu", width: 140, cell: (r) => archiveMono(r.no) },
  { key: "record", header: "Hồ sơ mượn", cell: (r) => bold(r.record) },
  { key: "borrower", header: "Người mượn", width: 200, cell: (r) => r.borrower },
  { key: "form", header: "Hình thức", width: 130, cell: (r) => r.form },
  { key: "due", header: "Hạn trả", width: 128, cell: (r) => r.due },
  { key: "status", header: "Trạng thái", width: 124, cell: (r) => archiveStatus(r.status) },
]
/** Borrow/return tracking (mượn - trả). */
export function ArchiveBorrowPage(props: ListProps<ArchiveLoan>) {
  return <ArchiveListPage<ArchiveLoan> searchPlaceholder="Tìm số phiếu, người mượn, lý do…" actionLabel="Đăng ký mượn" emptyTitle="Chưa có phiếu mượn" rowLabel={(r) => r.no} {...props} columns={loanColumns} getRowId={(r) => r.id} />
}

// ---- Destruction review
export interface ArchiveDestruction { id: string; code: string; title: string; year: number; records: number; step: string; status: ArchiveStatus }
const destructionColumns: ArchiveColumn<ArchiveDestruction>[] = [
  { key: "code", header: "Mã đợt", width: 150, cell: (r) => archiveMono(r.code) },
  { key: "title", header: "Tiêu đề", cell: (r) => bold(r.title) },
  { key: "year", header: "Năm", width: 66, align: "center", cell: (r) => r.year },
  { key: "records", header: "Số hồ sơ", width: 90, align: "right", cell: (r) => r.records },
  { key: "step", header: "Bước", width: 210, cell: (r) => r.step },
  { key: "status", header: "Trạng thái", width: 160, cell: (r) => archiveStatus(r.status) },
]
/** Destruction review (xét hủy): batches. */
export function ArchiveDestructionPage(props: ListProps<ArchiveDestruction>) {
  return <ArchiveListPage<ArchiveDestruction> searchPlaceholder="Tìm mã đợt, tiêu đề, số quyết định…" actionLabel="Lập đợt xét hủy" emptyTitle="Chưa có đợt xét hủy" rowLabel={(r) => r.code} {...props} columns={destructionColumns} getRowId={(r) => r.id} />
}

/** Records whose retention period is over (second tab of the destruction screen). */
export interface ArchiveDueRecord { id: string; code: string; title: string; year: number; retention: string; expired: string }
const dueColumns: ArchiveColumn<ArchiveDueRecord>[] = [
  { key: "code", header: "Mã hồ sơ", cell: (r) => archiveMono(r.code) },
  { key: "title", header: "Tiêu đề", cell: (r) => bold(r.title) },
  { key: "year", header: "Năm", cell: (r) => r.year },
  { key: "retention", header: "Thời hạn", cell: (r) => r.retention },
  { key: "expired", header: "Hết hạn từ", cell: (r) => r.expired },
]
export function ArchiveDueRecordsPage(props: ListProps<ArchiveDueRecord>) {
  return <ArchiveListPage<ArchiveDueRecord> searchPlaceholder="Tìm mã, tiêu đề…" emptyTitle="Chưa có hồ sơ đến hạn xét hủy" rowLabel={(r) => r.code} {...props} columns={dueColumns} getRowId={(r) => r.id} />
}

// ---- Submission (nộp lưu)
export interface ArchiveSubmission { id: string; no: string; title: string; records: number; date: string; unit?: string; status: ArchiveStatus }
const submissionColumns: ArchiveColumn<ArchiveSubmission>[] = [
  { key: "no", header: "Số phiếu", width: 150, cell: (r) => archiveMono(r.no) },
  { key: "title", header: "Tiêu đề đợt nộp", cell: (r) => bold(r.title) },
  { key: "records", header: "Hồ sơ", width: 110, align: "center", cell: (r) => r.records },
  { key: "date", header: "Ngày lập", width: 104, cell: (r) => r.date },
  { key: "status", header: "Trạng thái", width: 150, cell: (r) => archiveStatus(r.status) },
]
/** Submission slips (nộp lưu). */
export function ArchiveSubmissionPage(props: ListProps<ArchiveSubmission>) {
  return <ArchiveListPage<ArchiveSubmission> searchPlaceholder="Tìm số phiếu, tiêu đề, người giao, đơn vị…" actionLabel="Lập phiếu nộp lưu" emptyTitle="Không có phiếu nộp lưu" rowLabel={(r) => r.no} {...props} columns={submissionColumns} getRowId={(r) => r.id} />
}

// ---- Submission deadlines (nộp lưu lịch sử)
export interface ArchiveDeadline { id: string; code: string; title: string; year: number; form: string; due: string; slip?: string }
const deadlineColumns: ArchiveColumn<ArchiveDeadline>[] = [
  { key: "code", header: "Mã hồ sơ", width: 170, cell: (r) => archiveMono(r.code) },
  { key: "title", header: "Tiêu đề", cell: (r) => bold(r.title) },
  { key: "year", header: "Năm", width: 66, align: "center", cell: (r) => r.year },
  { key: "form", header: "Dạng", width: 100, cell: (r) => r.form },
  { key: "due", header: "Hạn nộp", width: 180, cell: (r) => r.due },
  { key: "slip", header: "Phiếu", width: 150, cell: (r) => r.slip ? archiveMono(r.slip) : <span className="text-muted-foreground">Chưa có phiếu</span> },
]
/** Records due for submission with registration slips. */
export function ArchiveDeadlinePage(props: ListProps<ArchiveDeadline>) {
  return <ArchiveListPage<ArchiveDeadline> searchPlaceholder="Tìm mã, tiêu đề, đơn vị…" actionLabel="Lập phiếu đăng ký" emptyTitle="Chưa có hồ sơ đến hạn" rowLabel={(r) => r.code} actionsColumn {...props} columns={deadlineColumns} getRowId={(r) => r.id} />
}

/** Registration slips (second tab of the submission-history screen). */
export interface ArchiveRegistration { id: string; no: string; title: string; records: number; date: string; status: ArchiveStatus }
const registrationColumns: ArchiveColumn<ArchiveRegistration>[] = [
  { key: "no", header: "Số phiếu", cell: (r) => archiveMono(r.no) },
  { key: "title", header: "Tiêu đề", cell: (r) => bold(r.title) },
  { key: "records", header: "Hồ sơ", cell: (r) => r.records },
  { key: "date", header: "Ngày lập", cell: (r) => r.date },
  { key: "status", header: "Trạng thái", cell: (r) => archiveStatus(r.status) },
]
export function ArchiveRegistrationPage(props: ListProps<ArchiveRegistration>) {
  return <ArchiveListPage<ArchiveRegistration> searchPlaceholder="Tìm mã, tiêu đề, đơn vị…" actionLabel="Lập phiếu đăng ký" emptyTitle="Chưa có phiếu đăng ký" rowLabel={(r) => r.no} {...props} columns={registrationColumns} getRowId={(r) => r.id} />
}

// ---- Fonds (danh mục phòng)
export interface ArchiveFondsRow { id: string; code: string; name: string; description?: string; period?: string; stages: number; status: ArchiveStatus }
const fondsColumns: ArchiveColumn<ArchiveFondsRow>[] = [
  { key: "code", header: "Mã phòng", width: 140, cell: (r) => archiveMono(r.code) },
  { key: "name", header: "Tên phòng", cell: (r) => (<div><div className="font-medium">{r.name}</div>{r.description && <div className="max-w-xl truncate text-xs text-muted-foreground">{r.description}</div>}</div>) },
  { key: "period", header: "Thời gian", width: 150, cell: (r) => r.period ?? <span className="text-muted-foreground">—</span> },
  { key: "stages", header: "Giai đoạn", width: 100, align: "center", cell: (r) => r.stages },
  { key: "status", header: "Trạng thái", width: 120, cell: (r) => archiveStatus(r.status) },
]
/** Fonds admin list (danh mục phòng). Tabs for TOC / retention periods / topic types are supplied by the caller. */
export function ArchiveFondsPage(props: ListProps<ArchiveFondsRow>) {
  return <ArchiveListPage<ArchiveFondsRow> searchPlaceholder="Tìm mã, tên phòng…" actionLabel="Thêm phòng" emptyTitle="Chưa có phòng" rowLabel={(r) => r.name} {...props} columns={fondsColumns} getRowId={(r) => r.id} />
}

/** Generic name/code/note row for the fonds sub-tabs (mục lục, thời hạn bảo quản, loại hồ sơ chuyên đề). */
export interface ArchiveRefRow { id: string; code: string; name: string; note?: string }
const refColumns: ArchiveColumn<ArchiveRefRow>[] = [
  { key: "code", header: "Mã", cell: (r) => archiveMono(r.code) },
  { key: "name", header: "Tên", cell: (r) => bold(r.name) },
  { key: "note", header: "Ghi chú", cell: (r) => r.note ?? <span className="text-muted-foreground">—</span> },
]
export function ArchiveRefPage(props: ListProps<ArchiveRefRow> & { addLabel?: string }) {
  const { addLabel = "Thêm mới", ...rest } = props
  return <ArchiveListPage<ArchiveRefRow> searchPlaceholder="Tìm mã, tên…" actionLabel={addLabel} emptyTitle="Chưa có dữ liệu" rowLabel={(r) => r.name} {...rest} columns={refColumns} getRowId={(r) => r.id} />
}

// ---- Access log (quản trị)
export interface ArchiveAuditRow { id: string; date: string; actor: string; action: string; detail: string; result: ArchiveStatus; hash: string }
const auditColumns: ArchiveColumn<ArchiveAuditRow>[] = [
  { key: "date", header: "Ngày", width: 104, cell: (r) => r.date },
  { key: "actor", header: "Người thực hiện", width: 220, cell: (r) => r.actor },
  { key: "action", header: "Thao tác", width: 160, cell: (r) => r.action },
  { key: "detail", header: "Chi tiết", cell: (r) => r.detail },
  { key: "result", header: "Kết quả", width: 120, cell: (r) => archiveStatus(r.result) },
  { key: "hash", header: "Mã băm", width: 130, cell: (r) => <span className="font-mono text-xs text-muted-foreground">{r.hash}</span> },
]
/** Access log list (embed inside ArchiveAdminPage with `bare`). */
export function ArchiveAuditPage(props: ListProps<ArchiveAuditRow>) {
  return <ArchiveListPage<ArchiveAuditRow> searchPlaceholder="Tìm chi tiết, người, đơn vị…" emptyTitle="Không có bản ghi" {...props} columns={auditColumns} getRowId={(r) => r.id} />
}

/** Generic administrative rows (integrity checks, change orders, incidents, media, backups). */
export interface ArchiveAdminRow { id: string; code: string; title: string; owner: string; date: string; status: ArchiveStatus }
const adminColumns: ArchiveColumn<ArchiveAdminRow>[] = [
  { key: "code", header: "Mã", cell: (r) => archiveMono(r.code) },
  { key: "title", header: "Nội dung", cell: (r) => bold(r.title) },
  { key: "owner", header: "Phụ trách", cell: (r) => r.owner },
  { key: "date", header: "Ngày", width: 104, cell: (r) => r.date },
  { key: "status", header: "Trạng thái", cell: (r) => archiveStatus(r.status) },
]
export function ArchiveAdminListPage(props: ListProps<ArchiveAdminRow>) {
  return <ArchiveListPage<ArchiveAdminRow> searchPlaceholder="Tìm mã, nội dung…" emptyTitle="Không có bản ghi" rowLabel={(r) => r.code} {...props} columns={adminColumns} getRowId={(r) => r.id} />
}

import * as React from "react"
import { MoveHorizontal, RefreshCw } from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { ChartContainer, ChartLegend, ChartLegendContent, ChartTooltip, ChartTooltipContent, Recharts, type ChartConfig } from "@/components/ui/chart"
import { DataTable, type Column } from "@/components/blocks/shell/data-table"
import { ArchiveSelect, ArchiveStat, type ArchiveSelectProps } from "./archive-shared"
import type { ArchiveStatus } from "./archive-lists"

export interface ArchiveReportMenuItem { id: string; code?: string; label: string }
/** `colorIndex` pins a datum to one --chart-N slot so the same entity keeps its colour across charts. */
export type ArchiveBarDatum = { label: string; value: number; colorIndex?: number }
export interface ArchiveKpi { label: string; value: React.ReactNode; hint?: React.ReactNode }
export interface ArchiveReportTableRow { id: string; name: string; sub?: string; status?: ArchiveStatus; values: number[] }

export interface ArchiveMultiLineSeries {
  key: string
  label: string
  color: string
}

export type ArchiveChartSpec =
  | { type: "bar"; title: string; data: ArchiveBarDatum[] }
  | { type: "hbar"; title: string; data: ArchiveBarDatum[] }
  | { type: "donut"; title: string; data: ArchiveBarDatum[] }
  | { type: "pie"; title: string; data: ArchiveBarDatum[] }
  | { type: "line"; title: string; data: ArchiveBarDatum[] }
  | {
      type: "multi-line"
      title: string
      data: Record<string, string | number>[]
      categoryKey?: string
      series: ArchiveMultiLineSeries[]
      height?: number
    }

export interface ArchiveReportPageProps {
  kpis: ArchiveKpi[]
  menu: ArchiveReportMenuItem[]
  activeReport: string
  onReportChange?: (id: string) => void
  title: string
  description?: string
  select?: ArchiveSelectProps
  onRefresh?: () => void
  summary?: { label: string; value: number }[]
  charts?: ArchiveChartSpec[]
  chartsLayout?: "grid" | "stacked"
  tableHeaders?: string[]
  tableRows?: ArchiveReportTableRow[]
}

/** Chart colour tokens, same palette as the home chart (--chart-1…6). */
const SERIES_VARS = ["var(--chart-1)", "var(--chart-2)", "var(--chart-3)", "var(--chart-4)", "var(--chart-5)", "var(--chart-6)"]
const SERIES_BG = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5", "bg-chart-6"]
const VALUE_CONFIG: ChartConfig = { value: { label: "Số lượng", color: SERIES_VARS[0] } }

function wrapLabel(text: string, maxCharsPerLine: number = 14, maxLines: number = 2): string[] {
  if (!text || text.length <= maxCharsPerLine) return [text]
  const words = text.split(" ")
  const lines: string[] = []
  let cur = ""

  for (let i = 0; i < words.length; i++) {
    const w = words[i]
    if (!cur) {
      cur = w
    } else if ((cur + " " + w).length <= maxCharsPerLine) {
      cur += " " + w
    } else {
      lines.push(cur)
      cur = w
      if (lines.length === maxLines - 1) {
        const rest = words.slice(i).join(" ")
        lines.push(rest.length > maxCharsPerLine ? `${rest.slice(0, maxCharsPerLine - 1)}…` : rest)
        cur = ""
        break
      }
    }
  }
  if (cur) lines.push(cur)
  return lines
}

interface HorizontalTickProps {
  x?: number
  y?: number
  payload?: {
    value?: string | number
  }
}

/** X-axis labels sit horizontally on one row and wrap automatically for long text or narrow screens. */
function HorizontalAxisTick({ x, y, payload }: HorizontalTickProps) {
  if (x === undefined || y === undefined || payload?.value === undefined) return null
  const label = String(payload.value)
  const lines = wrapLabel(label, 14, 2)

  return (
    <g transform={`translate(${x},${y})`}>
      <text
        x={0}
        y={8}
        textAnchor="middle"
        className="fill-muted-foreground text-[10.5px] sm:text-[11px] font-normal select-none pointer-events-none"
      >
        {lines.map((line, i) => (
          <tspan key={i} x={0} dy={i === 0 ? 0 : 13}>
            {line}
          </tspan>
        ))}
      </text>
    </g>
  )
}

/** Vertical bars with value axis, grid, tooltip and value labels (Recharts). */
export function ArchiveBarChart({ data, label }: { data: ArchiveBarDatum[]; height?: number; label: string }) {
  const hasLongLabels = data.some((d) => d.label.length > 8)
  // Each column needs about 135px (long labels) or 95px (short labels)
  // so horizontal labels never overlap each other
  const colWidth = hasLongLabels ? 135 : 95
  const calculatedMinWidth = data.length * colWidth + 50
  const isScrollable = data.length >= 3

  return (
    <div className="w-full outline-none focus:outline-none">
      {isScrollable && (
        <div className="mb-2 flex items-center justify-end gap-1.5 text-xs text-muted-foreground lg:hidden select-none">
          <span>Kéo ngang để xem đầy đủ ({data.length} cột)</span>
          <MoveHorizontal className="size-3.5" aria-hidden="true" />
