const columns: ArchiveColumn<ArchiveRecord>[] = [
  { key: "code", header: "Mã hồ sơ", width: 160, cell: (r) => archiveMono(r.code) },
  { key: "title", header: "Tiêu đề", cell: (r) => <span className="font-medium">{r.title}</span> },
